static int check_result(dmg_result* r,unsigned count){dmg_result_info info;unsigned i;CHECK(dmg_result_get_info(r,&info)==DMG_OK&&info.candidates_count==count);for(i=0;i<count;i++){dmg_method_type_identity_v1 id;dmg_method_row row;dmg_witness w,old;uint32_t n=0,j,seen=0;CHECK(dmg_result_get_method_type_identity_v1(r,i,&id,sizeof(id))==DMG_OK);CHECK(dmg_result_get_method(r,i,&row)==DMG_OK&&row.method_index==id.method_ref);CHECK(dmg_result_get_witness_count(r,i,&n)==DMG_OK&&n==4);memset(&old,0xa5,sizeof(old));w=old;CHECK(dmg_result_get_witness(r,i,0,&w)==DMG_UNSUPPORTED&&!memcmp(&w,&old,sizeof(w)));for(j=0;j<n;j++){CHECK(dmg_result_get_method_witness_v1(r,i,j,&w,sizeof(w))==DMG_OK);seen|=1u<<w.kind;if(w.kind==DMG_WITNESS_TYPE_USE){dmg_method_type_witness_v1 d;uint16_t text[128];unsigned k;const char* expected="Lfixture/MethodTypeCases$Target;";CHECK(dmg_result_get_method_type_witness_v1(r,i,j,&d,sizeof(d))==DMG_OK&&d.source_index==id.source_index&&d.method_ordinal==id.method_ordinal&&d.descriptor_length==strlen(expected));memset(text,0xa5,sizeof(text));CHECK(dmg_result_copy_method_type_descriptor_v1(r,i,j,text,d.descriptor_length-1)==DMG_INVALID_ARGUMENT&&text[0]==0xa5a5);CHECK(dmg_result_copy_method_type_descriptor_v1(r,i,j,text,d.descriptor_length)==DMG_OK);for(k=0;k<d.descriptor_length;k++)CHECK(text[k]==(unsigned char)expected[k]);CHECK(w.dex_pc==8&&w.opcode==34);}}
 CHECK(seen==((1u<<DMG_WITNESS_STRING)|(1u<<DMG_WITNESS_INVOKE)|(1u<<DMG_WITNESS_FIELD)|(1u<<DMG_WITNESS_TYPE_USE)));}return 0;}
int main(int argc,char** argv){dmg_engine* e=NULL;dmg_snapshot* s=NULL;dmg_query* q=NULL;dmg_result* r=NULL;dmg_job* job=NULL;dmg_batch* batch=NULL;dmg_query_info qi;dmg_error error={0};dmg_job_options jo={sizeof(jo),DMG_ABI_VERSION,1,1,0};dmg_relation_job_status st;dmg_source_spec spec={0};dmg_source_set_options so={sizeof(so),DMG_ABI_VERSION,"method-type-c",1,8,1u<<20};FILE* f;long size;unsigned char* bytes;unsigned batches=0;CHECK(argc==2);f=fopen(argv[1],"rb");CHECK(f&&fseek(f,0,SEEK_END)==0);size=ftell(f);CHECK(size>0&&fseek(f,0,SEEK_SET)==0);bytes=malloc((size_t)size);CHECK(bytes&&fread(bytes,1,(size_t)size,f)==(size_t)size);fclose(f);CHECK(dmg_engine_create(NULL,&e,&error)==DMG_OK);spec.struct_size=sizeof(spec);spec.abi_version=DMG_ABI_VERSION;spec.format=DMG_INPUT_RAW_DEX;spec.data=bytes;spec.size=size;spec.slot_key="base";spec.role="base";CHECK(dmg_snapshot_open_sources(e,&spec,1,&so,&s,&error)==DMG_OK);free(bytes);CHECK(dmg_query_compile_json(e,(const uint8_t*)query,strlen(query),&q,&error)==DMG_OK);CHECK(dmg_query_get_info(q,&qi)==DMG_OK&&!strncmp(qi.query_id,"query:v22:",10));CHECK(dmg_query_execute(s,q,&r,&error)==DMG_OK&&check_result(r,1)==0);dmg_result_release(r);CHECK(dmg_job_start(s,q,&jo,&job,&error)==DMG_OK);for(;;){dmg_status code=dmg_job_next(job,15000,&batch,&error);if(code==DMG_END_OF_STREAM)break;CHECK(code==DMG_OK&&batch&&check_result(batch,1)==0);batches++;dmg_batch_release(batch);batch=NULL;}CHECK(dmg_job_wait_relation(job,15000,&st,sizeof(st))==DMG_OK&&st.terminal&&st.outcome.execution_status==DMG_OK&&batches==1);dmg_job_release(job);dmg_query_release(q);dmg_snapshot_release(s);dmg_engine_release(e);puts("PASS C v22 mixed witness, copy guard and Job");return 0;}
